import { printAst } from '~/ast';
import { definitionNodes } from '~/generator';
import type { DefinitionOptions } from '~/generator';

export type { DefinitionOptions } from '~/generator';
export { generateDeclarations } from '~/module';
export type { DeclarationOptions } from '~/module';

/** Generate standalone OpenAPI interfaces without a runtime dependency. */
export function generateDefinitions(document: object, options: DefinitionOptions = {}): string {
  return (
    '/** Generated by OpenTyped OAPI. Do not edit. */\n' +
    printAst(definitionNodes(document, options))
  );
}
